//! 🧪️ Original slot contracts require resident borrowed read and return ports.
use semio_framework_value_original_slot::{RetainedOriginalSlot,RetainedOriginalRead};
#[test]fn original_slot_native_owner_birth_fits_original_copy_bound(){let law:serde_json::Value=serde_json::from_str(include_str!("resident.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("resident.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v)}let d=RetainedOriginalRead::<String>::initial_demands();assert!(d.copy_bytes+d.capacity_bytes<=law["maximumReadBirthTotal"].as_u64().unwrap()as usize,"original coupled read birth copies {} and allocates {}; read layout {}",d.copy_bytes,d.capacity_bytes,std::mem::size_of::<RetainedOriginalRead<String>>());assert!(d.copy_bytes<=law["maximumCopyBytes"].as_u64().unwrap()as usize,"actual read frame copies {}",d.copy_bytes);let slot=RetainedOriginalSlot::new(law["value"].as_str().unwrap().to_owned());let key=slot.key();assert!(slot.demands(key,4096).is_ok());assert!(!slot.has_read());assert_eq!(slot.get(),law["value"].as_str().unwrap());}

use semio_framework_value_original_slot::{RetainedOriginalSlotKey,ArtifactOwnedValueRetirementFactory,FactoryAuthority};
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::{mem::ManuallyDrop,sync::Arc};
#[derive(Clone,Copy,PartialEq,Eq,Debug)]enum Op{Advance,Retain,CloseLease,Return,RetireSlot,RetireFactory,RetireReturned}
struct Context<'a>{source:RetainedCloneRef<'a,u64>,turn:OriginalSourceTurnIdentity,op:Op}
struct Producer{slot:ManuallyDrop<Option<RetainedOriginalSlot<String>>>,key:RetainedOriginalSlotKey,factory:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>>,returned:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>>,factory_close:ManuallyDrop<Option<FactoryAuthority>>,returned_close:ManuallyDrop<Option<FactoryAuthority>>,lease:ManuallyDrop<RetainedOwnedProjectionAdmission<String>>,retirement:ManuallyDrop<RetainedCloneClose>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity,selected:Option<(OriginalEffectInvocationIdentity,Op)>}
impl Producer{
 fn empty(&self)->bool{self.selected.is_none()&&self.slot.is_none()&&self.factory.is_none()&&self.returned.is_none()&&self.lease.terminal_is_empty()&&self.retirement.is_empty()&&self.factory_close.as_ref().is_none_or(FactoryAuthority::terminal_is_empty)&&self.returned_close.as_ref().is_none_or(FactoryAuthority::terminal_is_empty)}
 fn dispatch<'r>(&mut self,c:&mut Context<'_>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{
  let invocation=effect.invocation().ok_or_else(||ValueError::invariant("slot law invocation absent"))?;if invocation.mode()!=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive}{return Err(ValueError::invariant("slot law invocation changed"))}let key=(invocation.identity(),c.op);if recover&&self.selected!=Some(key)||!recover&&self.selected.is_some(){return Err(ValueError::invariant("slot law route changed"))}
  let state=self;let mut scope=reply.progress().scope(&mut state.selected,key)?;
  match c.op{
   Op::Advance=>{let slot=state.slot.as_mut().unwrap();let factory=state.factory.as_ref().unwrap();drop(if recover{slot.recover_advance_read_into(state.key,factory,effect,scope.borrow()?)?}else{slot.advance_read_into(state.key,factory,effect,scope.borrow()?)?});}
   Op::Retain=>{if recover{return Err(ValueError::invariant("native alias admission has no unrecorded callback"))}let mut result=None;drop(state.slot.as_ref().unwrap().retain_read_into(state.key,&mut state.lease,effect,OriginalEffectReply::borrow(&mut result)?)?);drop(semio_framework_value_retirement::forward_original_value_reply(&mut result,scope.borrow()?)?);}
   Op::CloseLease=>{drop(if recover{state.lease.recover_close_into(effect,scope.borrow()?)?}else{state.lease.close_into(effect,scope.borrow()?)?});}
   Op::Return=>{let slot=state.slot.as_mut().unwrap();drop(if recover{slot.recover_return_read_into(state.key,&mut state.returned,effect,scope.borrow()?)?}else{slot.return_read_into(state.key,&mut state.returned,effect,scope.borrow()?)?});}
   Op::RetireSlot=>{if state.retirement.is_empty(){if recover{return Err(ValueError::invariant("native slot retirement birth has no unrecorded callback"))}let turn=state.retirement.begin_granted(&mut state.slot,effect);drop(scope.borrow()?.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)));}else{drop(if recover{state.retirement.recover_step_into(effect,scope.borrow()?)?}else{state.retirement.step_into(effect,scope.borrow()?)?});}}
   Op::RetireFactory|Op::RetireReturned=>{let(input,owner)=if c.op==Op::RetireFactory{(&mut state.factory,&mut state.factory_close)}else{(&mut state.returned,&mut state.returned_close)};if owner.is_none(){if recover{return Err(ValueError::invariant("native issuer capture has no unrecorded callback"))}let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>>()+std::mem::size_of::<Option<FactoryAuthority>>(),depth:1,..Default::default()};assert!(retained_clone_grant_admits(effect.grant(),d));assert!(effect.performed(1)?);**owner=Some(FactoryAuthority::new(input.take().unwrap()));drop(scope.borrow()?.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))));}else{drop(if recover{owner.as_mut().unwrap().recover_step_into(effect,scope.borrow()?)?}else{owner.as_mut().unwrap().step_into(effect,scope.borrow()?)?});}}
  }Ok(scope.forwarded())
 }
 fn quote(&self,op:Op)->(RetirementDemand,u64){match op{
  Op::Advance=>{let slot=self.slot.as_ref().unwrap();(slot.demands(self.key,4096).unwrap(),slot.read_work_demand(self.key,4096).unwrap())}
  Op::Retain=>{let slot=self.slot.as_ref().unwrap();(slot.retain_read_demand(self.key,&self.lease).unwrap(),slot.retain_read_work_demand(self.key,&self.lease).unwrap())}
  Op::CloseLease=>(self.lease.close_demand(4096).unwrap(),self.lease.close_work_demand(4096).unwrap()),
  Op::Return=>{let slot=self.slot.as_ref().unwrap();(slot.return_demands(self.key,4096).unwrap(),slot.return_work_demand(self.key,4096).unwrap())}
  Op::RetireSlot=>{assert!(!self.retirement.requires_original_birth());assert!(!self.retirement.requires_original_control());(self.retirement.next_owner_demands::<RetainedOriginalSlot<String>>(self.slot.is_some(),&None,4096).unwrap(),self.retirement.next_owner_work::<RetainedOriginalSlot<String>>(self.slot.is_some(),&None,4096).unwrap())}
  Op::RetireFactory|Op::RetireReturned=>{let owner=if op==Op::RetireFactory{&self.factory_close}else{&self.returned_close};if let Some(owner)=owner.as_ref(){assert!(!owner.requires_original_birth());assert!(!owner.requires_original_control());(owner.demands(4096).unwrap(),owner.next_computational_work(4096).unwrap())}else{(RetirementDemand{copy_bytes:std::mem::size_of::<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>>()+std::mem::size_of::<Option<FactoryAuthority>>(),depth:1,..Default::default()},1)}}
 }}
}
impl Drop for Producer{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.empty());unsafe{ManuallyDrop::drop(&mut self.slot);ManuallyDrop::drop(&mut self.factory);ManuallyDrop::drop(&mut self.returned);ManuallyDrop::drop(&mut self.factory_close);ManuallyDrop::drop(&mut self.returned_close);ManuallyDrop::drop(&mut self.lease);ManuallyDrop::drop(&mut self.retirement)}}}
impl OriginalEffectProducer for Producer{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a>where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("slot law changed actual Source"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,false)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,true)}}
struct Loan<'a>(&'a mut Producer);
impl OriginalEffectProducer for Loan<'_>{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a>where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{self.0.validate_context(c)}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{self.0.source_turn(c)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.0.receive(c,e,r)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.0.recover(c,e,r)}}
fn grant_for(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn original_slot_borrows_fences_and_returns_under_one_actual_source(){let law:serde_json::Value=serde_json::from_str(include_str!("resident.json")).unwrap();for direct in [true,false]{for cut in law["cancellationCuts"].as_array().unwrap().iter().rev(){let cut=cut.as_u64().unwrap();let text=law["value"].as_str().unwrap().to_owned();let pointer=text.as_ptr();let slot=RetainedOriginalSlot::new(text);let key=slot.key();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());let factory_pointer=Arc::as_ptr(&factory)as*const()as usize;let mut source=RetainedCloneSource::<u64>::from_owner(73);let id=source.borrow().reference_identity();let turn=source.with_bank(|_,bank|bank.source_witness().identity()).unwrap();let mut resident=Producer{slot:ManuallyDrop::new(Some(slot)),key,factory:ManuallyDrop::new(Some(factory)),returned:ManuallyDrop::new(None),factory_close:ManuallyDrop::new(None),returned_close:ManuallyDrop::new(None),lease:ManuallyDrop::new(Default::default()),retirement:ManuallyDrop::new(Default::default()),source:id,turn,selected:None};let mut authority=Some(OriginalEffectAuthority::new(Loan(&mut resident)));let mut action=None;let mut answer=None;let mut op=Op::Advance;let mut blocked=0;let mut observed=(0usize,0usize);
 for tick in 0..10000{let p=authority.as_ref().unwrap();if op==Op::Advance{if p.inspect(|p|p.0.slot.as_ref().unwrap().borrow(key).is_ok()){op=Op::Retain}else if tick as u64>=cut{op=if direct{Op::RetireSlot}else{Op::Return}}}
 if op==Op::Retain&&p.inspect(|p|p.0.lease.borrow().is_ok()){assert_eq!(p.inspect(|p|p.0.lease.borrow().unwrap().get().as_ptr()),pointer);op=Op::Return}
 if op==Op::Return&&p.inspect(|p|!p.0.lease.terminal_is_empty()){if blocked==8{op=Op::CloseLease}else{blocked+=1;assert!(p.inspect(|p|p.0.returned.is_none()))}}
 if op==Op::CloseLease&&p.inspect(|p|p.0.lease.terminal_is_empty()){op=if direct{Op::RetireSlot}else{Op::Return}}
 if op==Op::Return&&p.inspect(|p|!p.0.slot.as_ref().unwrap().has_read()){p.inspect(|p|{assert_eq!(p.0.slot.as_ref().unwrap().get().as_ptr(),pointer);if let Some(factory)=p.0.returned.as_ref(){assert_eq!(Arc::as_ptr(factory)as*const()as usize,factory_pointer)}});op=Op::RetireSlot}
 if op==Op::RetireSlot&&p.inspect(|p|p.0.slot.is_none()&&p.0.retirement.is_empty()){op=Op::RetireFactory}
 if op==Op::RetireFactory&&p.inspect(|p|p.0.factory.is_none()&&p.0.factory_close.as_ref().is_some_and(FactoryAuthority::terminal_is_empty)){if p.inspect(|p|p.0.returned.is_some()){op=Op::RetireReturned}else{break}}
 if op==Op::RetireReturned&&p.inspect(|p|p.0.returned.is_none()&&p.0.returned_close.as_ref().is_some_and(FactoryAuthority::terminal_is_empty)){break}
 let(d,work)=p.inspect(|p|p.0.quote(op));if op==Op::Advance{assert!(d.copy_bytes+d.capacity_bytes<=law["maximumReadBirthTotal"].as_u64().unwrap()as usize,"read birth step {tick} copies {} and allocates {}",d.copy_bytes,d.capacity_bytes)}assert!(d.copy_bytes<=4096,"step {tick} {op:?} direct={direct} cut={cut} copies {}; source owner={} slot retirement={}",d.copy_bytes,std::mem::size_of::<RetainedOriginalRead<String>>(),std::mem::size_of::<<RetainedOriginalSlot<String>as semio_framework_value_retirement::RetireOwned>::RetirementCursor>());let grant=grant_for(d);
 loop{let((poll,actual),heap)=source.with_bank(|original,bank|{let step=observe(||bank.run_with_source(grant,work,|effect,witness|{let before=effect.performed_work();let mut context=Context{source:original,turn:witness.identity(),op};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap_or_else(|error|panic!("slot tick {tick} {op:?} direct={direct} cut={cut}: {error:?}"));let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));observed.0+=step.1.0;observed.1+=step.1.1;if let RetainedWorkPoll::Complete(_)=step.0.0{assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.as_ref().unwrap().as_ref().unwrap_or_else(|error|panic!("slot step {tick} {op:?}: {error:?}"));assert_eq!(observed,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,observed);observed=(0,0)}step}).unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}if let RetainedWorkPoll::Complete(done)=poll{done.result.unwrap();answer.take().unwrap().unwrap();break}}
 }
 assert!(authority.as_ref().unwrap().inspect(|p|p.0.empty()),"slot lifecycle did not finish direct={direct} cut={cut}");
 source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<Loan<'_>>::producer_transfer_demand().unwrap();assert!(d.copy_bytes<=4096);let grant=grant_for(d);let mut loan=None;let((poll,_),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let context=Context{source:original,turn:witness.identity(),op:Op::RetireFactory};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut loan,effect))}));let RetainedWorkPoll::Complete(done)=poll else{panic!("loan return pending")};let p=done.result.unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(p,grant,heap);let witness=unsafe{RetainedCursorRelease::native(|loan:&Loan<'_>|loan.0.empty())};let grant=grant_for(witness.inline_demand());let mut reply=None;let((_,_),heap)=observe(||bank.run(grant,1,|effect|{let before=effect.performed_work();drop(witness.inline_into(&mut loan,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert_eq!(bank.take_admitted(),Some(true));bank.post(reply.take().unwrap().unwrap().progress(),grant,heap)}).unwrap();drop(authority);assert!(resident.empty());drop(resident);for _ in 0..10000{if source.terminal_is_empty(){break}assert!(!matches!(source.close_once().unwrap(),FixtureCloseStep::Denied|FixtureCloseStep::Blocked))}assert!(source.terminal_is_empty());
 }}}
